    19	/// Issue a `WriteRead` dm ioctl over a growing byte buffer, retrying with
    20	/// a doubled buffer while the kernel reports `DM_BUFFER_FULL_FLAG`. Used
    21	/// by `Control::list`, `Device::table`/`Device::info`, and `Device::message` —
    22	/// every ioctl with variable-length output.
    23	///
    24	/// `payload` is written immediately after the header on every attempt
    25	/// (including retries) — used by `Device::message` to carry the
    26	/// `dm_target_msg` sector+string; the other two callers pass `&[]`.
    27	///
    28	/// `ioctl` is a closure rather than an `Ioctl<WriteRead, _>` value passed
    29	/// directly: `Ioctl`'s direction markers (`Read`/`Write`/`WriteRead`)
    30	/// don't derive `Copy`/`Clone`, so `Ioctl<WriteRead, _>` isn't actually
    31	/// `Copy` despite the outer type deriving it — a closure that references
    32	/// the `const DM_*` ioctl declaration re-materializes it fresh on every
    33	/// call instead of trying to move the same value repeatedly.
    34	// `DmHeader` is a cheap Copy value (a 312-byte plain struct, no heap data)
    35	// deliberately passed by value here so callers don't need to manage its
    36	// lifetime across retries; `#[allow]` because clippy's size heuristic
    37	// doesn't distinguish "cheap to copy" from "large".
    38	#[allow(clippy::large_types_passed_by_value)]
    39	pub(crate) fn ioctl_with_growing_buffer(
    40	    control: &File,
    41	    op: &'static str,
    42	    ioctl: impl Fn(&File, &mut DmHeader) -> std::io::Result<std::os::raw::c_uint>,
    43	    header: DmHeader,
    44	    payload: &[u8],
    45	    initial_cap: usize,
    46	) -> Result<Vec<u8>, Error> {
    47	    let mut cap = initial_cap.max(DmHeader::SIZE + payload.len());
    48	    loop {
    49	        let mut buf = vec![0u8; cap];
    50	        let mut h = header;
    51	        // Real dm ioctl buffers never approach u32::MAX; the kernel's own
    52	        // dm_ioctl.data_size field is itself a u32.
    53	        #[allow(clippy::cast_possible_truncation)]
    54	        h.set_data_size(buf.len() as u32);
    55	        buf[..DmHeader::SIZE].copy_from_slice(h.as_bytes());
    56	        buf[DmHeader::SIZE..DmHeader::SIZE + payload.len()].copy_from_slice(payload);
    57	
    58	        let (header_mut, _) = zerocopy::FromBytes::mut_from_prefix(&mut buf)
    59	            .expect("buf is at least DmHeader::SIZE bytes");
