   238	    fn next(&mut self) -> Option<Self::Item> {
   239	        // `checked_add` guards a kernel-controlled `next` from overflowing
   240	        // `usize` on 32-bit targets (matches `TableStatusIter`); on overflow
   241	        // we stop.
   242	        let record_end = self.offset.checked_add(12)?;
