   277	    // Test-only helper building tiny fixture buffers; lengths never approach u32::MAX.
   278	    #[allow(clippy::cast_possible_truncation)]
   279	    fn synthetic_list_devices_response(entries: &[(u64, &str)]) -> (Vec<u8>, usize, usize) {
   280	        let start = DmHeader::SIZE;
   281	        let mut lens = Vec::with_capacity(entries.len());
   282	        let mut payload_len = 0usize;
   283	        for (_, name) in entries {
   284	            // 8 (dev) + 4 (next) + name + NUL, 8-byte aligned (matches
   285	            // real dm_name_list chaining in practice, though the kernel
   286	            // doesn't strictly require alignment for the *last* entry).
   287	            let len = (12 + name.len() + 1).next_multiple_of(8);
   288	            lens.push(len);
   289	            payload_len += len;
   290	        }
   291	        let mut bytes = vec![0u8; start + payload_len];
   292	
   293	        let mut offset = start;
   294	        for (i, (dev, name)) in entries.iter().enumerate() {
   295	            let len = lens[i];
   296	            let next = if i == entries.len() - 1 {
   297	                0
   298	            } else {
   299	                len as u32
   300	            };
   301	            bytes[offset..offset + 8].copy_from_slice(&dev.to_ne_bytes());
   302	            bytes[offset + 8..offset + 12].copy_from_slice(&next.to_ne_bytes());
   303	            bytes[offset + 12..offset + 12 + name.len()].copy_from_slice(name.as_bytes());
   304	            offset += len;
   305	        }
   306	
   307	        (bytes, start, start + payload_len)
   308	    }
