   332	fn parse_message_reply(buf: &[u8]) -> Option<String> {
   333	    let (parsed, _): (&DmHeader, _) =
   334	        zerocopy::FromBytes::ref_from_prefix(buf).expect("buf is at least DmHeader::SIZE bytes");
