    91	/// One `<start> <length> <target>` row of a `DM_TABLE_STATUS` response,
    92	/// tagged by its [`mode`]. The params string is private: reach it through
    93	/// the mode-checked [`Row::parse`], which returns the reconstructed target
    94	/// ([`mode::Spec`]) or its runtime status ([`mode::Info`]).
    95	///
    96	/// The mode tag is load-bearing: a [`mode::Info`] row exposes only
    97	/// `parse::<T>() -> Option<T::Info>` (runtime status), never a
    98	/// reconstructed target — the target-returning `parse` is defined solely
    99	/// on `Row<mode::Spec>`. This will not compile:
   100	///
   101	/// ```compile_fail
   102	/// # use devmap::{Row, mode, targets::Linear};
   103	/// fn wrong(row: Row<mode::Info>) {
   104	///     // `parse::<Linear>()` on an Info row would return `Option<Linear::Info>`,
   105	///     // and `let _: Option<Linear>` forces the target interpretation the
   106	///     // Info mode never provides — a type error.
   107	///     let _target: Option<Linear> = row.parse::<Linear>();
   108	/// }
   109	/// ```
   110	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
   111	pub struct Row<M: mode::Mode> {
   112	    start: u64,
   113	    length: u64,
   114	    type_name: String,
   115	    params: String,
   116	    _mode: PhantomData<M>,
   117	}
   118	
   119	impl<M: mode::Mode> Row<M> {
   120	    /// The row's starting sector.
   121	    pub fn start(&self) -> u64 {
   122	        self.start
   123	    }
   124	    /// The row's length in sectors.
   125	    pub fn length(&self) -> u64 {
   126	        self.length
   127	    }
   128	    /// The kernel target type name for this row.
   129	    pub fn type_name(&self) -> &str {
   130	        &self.type_name
   131	    }
   132	}
   133	
   134	impl Row<mode::Spec> {
   135	    /// Reconstruct the target `T` from this table row, or `None` if the
   136	    /// row is a different target type or the params don't parse.
   137	    pub fn parse<T: Target + FromStr>(&self) -> Option<T> {
   138	        if self.type_name == T::TYPE_NAME {
   139	            self.params.parse::<T>().ok()
   140	        } else {
   141	            None
   142	        }
   143	    }
   144	}
   145	
   146	impl Row<mode::Info> {
   147	    /// Parse this status row as target `T`'s runtime status
   148	    /// ([`Target::Info`]), or `None` on a type-name or parse mismatch.
   149	    pub fn parse<T: Target>(&self) -> Option<T::Info> {
   150	        if self.type_name == T::TYPE_NAME {
   151	            self.params.parse::<T::Info>().ok()
   152	        } else {
   153	            None
   154	        }
   155	    }
   156	}
