   158	impl<M: mode::Mode> fmt::Display for Row<M> {
   159	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
   160	        if self.params.is_empty() {
   161	            write!(f, "{} {} {}", self.start, self.length, self.type_name)
   162	        } else {
   163	            write!(
   164	                f,
   165	                "{} {} {} {}",
   166	                self.start, self.length, self.type_name, self.params
   167	            )
   168	        }
   169	    }
   170	}
