   172	/// A streaming builder for `DM_TABLE_LOAD`: each [`add`](TableBuilder::add)
   173	/// renders a target directly into one growing buffer. Terminate with
   174	/// [`load`](TableBuilder::load). Obtained from [`crate::Device::builder`].
   175	#[derive(Debug)]
   176	pub struct TableBuilder {
   177	    control: Arc<File>,
   178	    buf: Vec<u8>,
   179	    count: u32,
   180	    last_spec_off: Option<usize>,
   181	    rendered: Vec<String>,
   182	}
   183	
   184	impl TableBuilder {
   185	    pub(crate) fn new(control: Arc<File>, dev: DevId) -> Self {
   186	        let mut buf = Vec::with_capacity(DmHeader::SIZE + 256);
   187	        buf.extend_from_slice(DmHeader::by_dev(dev.to_dev_t()).as_bytes());
   188	        Self {
   189	            control,
   190	            buf,
   191	            count: 0,
   192	            last_spec_off: None,
   193	            rendered: Vec::new(),
   194	        }
   195	    }
   196	
   197	    /// Append a target mapping sectors `[start, start + length)`.
   198	    ///
   199	    /// # Errors
   200	    ///
   201	    /// [`Error::Usage`] if `T::TYPE_NAME` is invalid, or if the target
   202	    /// renders an interior NUL into its params (which would truncate the
   203	    /// table line).
   204	    // Table buffers never approach u32::MAX; the kernel's own fields are u32.
   205	    // `target` is taken by value (the builder owns each row's rendering) even
   206	    // though it's only read through `Display`.
   207	    #[allow(clippy::cast_possible_truncation, clippy::needless_pass_by_value)]
   208	    pub fn add<T: Target + fmt::Display>(
   209	        mut self,
   210	        start: u64,
   211	        length: u64,
   212	        target: T,
   213	    ) -> Result<Self, Error> {
   214	        let name = T::TYPE_NAME.as_bytes();
   215	        if name.is_empty()
   216	            || name.len() >= DM_MAX_TYPE_NAME
   217	            || name.iter().any(|b| *b == 0 || b.is_ascii_whitespace())
   218	        {
   219	            return Err(Error::Usage(format!(
   220	                "invalid dm target type name: {:?}",
   221	                T::TYPE_NAME
   222	            )));
   223	        }
   224	
   225	        let mut params = String::new();
   226	        write!(params, "{target}").expect("Display into String is infallible");
   227	        if params.as_bytes().contains(&0) {
   228	            return Err(Error::Usage(format!(
   229	                "target {} rendered an interior NUL in its params",
   230	                T::TYPE_NAME
   231	            )));
   232	        }
   233	
   234	        let spec_off = self.buf.len();
   235	        if let Some(prev) = self.last_spec_off {
   236	            // Write-side `next`: byte offset from the previous spec's start
   237	            // to this one.
   238	            let delta = (spec_off - prev) as u32;
   239	            self.buf[prev + 20..prev + 24].copy_from_slice(&delta.to_ne_bytes());
   240	        }
   241	
   242	        let mut target_type = [0u8; DM_MAX_TYPE_NAME];
   243	        target_type[..name.len()].copy_from_slice(name);
   244	        let spec = dm_target_spec_raw {
   245	            sector_start: start,
   246	            length,
   247	            status: 0,
   248	            next: 0,
   249	            target_type,
   250	        };
   251	        self.buf.extend_from_slice(spec.as_bytes());
   252	
   253	        self.buf.extend_from_slice(params.as_bytes());
   254	        self.buf.push(0);
   255	        let block = DM_TARGET_SPEC_SIZE + params.len() + 1;
   256	        self.buf.resize(spec_off + block.next_multiple_of(8), 0);
   257	
   258	        self.rendered.push(if params.is_empty() {
   259	            format!("{start} {length} {}", T::TYPE_NAME)
   260	        } else {
   261	            format!("{start} {length} {} {params}", T::TYPE_NAME)
   262	        });
   263	        self.last_spec_off = Some(spec_off);
   264	        self.count += 1;
   265	        Ok(self)
   266	    }
   267	
   268	    /// Issue `DM_TABLE_LOAD`, staging the accumulated table into the
   269	    /// device's inactive slot. Activate with [`crate::Device::resume`].
   270	    ///
   271	    /// # Errors
   272	    ///
   273	    /// [`Error::DmIoctl`] (with the rendered table attached) if the kernel
   274	    /// rejects the table.
   275	    // The `mut_from_prefix` expects never fire: the buffer always begins with
   276	    // a `DmHeader` (written in `new`), so this is not a real panic path.
   277	    #[allow(clippy::cast_possible_truncation, clippy::missing_panics_doc)]
   278	    pub fn load(mut self) -> Result<(), Error> {
   279	        let total = self.buf.len() as u32;
   280	        {
   281	            let (header, _) =
   282	                DmHeader::mut_from_prefix(&mut self.buf).expect("buf begins with a DmHeader");
   283	            let header: &mut DmHeader = header;
   284	            header.set_data_size(total);
   285	            header.set_target_count(self.count);
   286	        }
   287	        let (header, _) =
   288	            DmHeader::mut_from_prefix(&mut self.buf).expect("buf begins with a DmHeader");
   289	        let header: &mut DmHeader = header;
   290	        DM_TABLE_LOAD
   291	            .ioctl(&*self.control, header)
   292	            .map_err(|source| Error::DmIoctl {
   293	                op: "DM_TABLE_LOAD",
   294	                source,
   295	                // ` | `-joined so the whole error stays on one line in loggers;
   296	                // omitted entirely for an empty table so there's no `(table: )`.
   297	                table_line: (!self.rendered.is_empty()).then(|| self.rendered.join(" | ")),
   298	            })?;
   299	        check_version("DM_TABLE_LOAD", header)
   300	    }
   301	}
