   303	/// Parses a `DM_TABLE_STATUS` response into [`Row`]s. Not exported —
   304	/// `Device::table`/`Device::info` return `impl Iterator<Item = Row<_>>`.
   305	///
   306	/// `dm_target_spec.next` here is the byte offset from the *first* spec's
   307	/// start to the next one (the read-direction convention, opposite the
   308	/// write side — see `<linux/dm-ioctl.h>`).
   309	pub(crate) struct TableStatusIter<M: mode::Mode> {
   310	    buf: Vec<u8>,
   311	    first: usize,
   312	    offset: usize,
   313	    remaining: u32,
   314	    _mode: PhantomData<M>,
   315	}
   316	
   317	impl<M: mode::Mode> TableStatusIter<M> {
   318	    /// `data_start` is the kernel-reported offset of the first spec (the
   319	    /// base for read-side `next`); callers pass it clamped to `buf.len()`.
   320	    pub(crate) fn new(buf: Vec<u8>, data_start: usize, target_count: u32) -> Self {
   321	        Self {
   322	            buf,
   323	            first: data_start,
   324	            offset: data_start,
   325	            remaining: target_count,
   326	            _mode: PhantomData,
   327	        }
   328	    }
   329	}
   330	
   331	impl<M: mode::Mode> Iterator for TableStatusIter<M> {
   332	    type Item = Row<M>;
   333	
   334	    // The fixed-width `try_into().unwrap()`s below operate on a slice bounded
   335	    // to exactly `DM_TARGET_SPEC_SIZE`, so they cannot panic.
   336	    #[allow(clippy::missing_panics_doc)]
   337	    fn next(&mut self) -> Option<Self::Item> {
   338	        if self.remaining == 0 {
   339	            return None;
   340	        }
   341	        // `checked_add` guards against a kernel-controlled `next` overflowing
   342	        // `usize` on 32-bit targets; on overflow we simply stop.
   343	        let end = self.offset.checked_add(DM_TARGET_SPEC_SIZE)?;
   344	        if end > self.buf.len() {
   345	            return None;
   346	        }
   347	
   348	        let spec = &self.buf[self.offset..end];
   349	        let sector_start = u64::from_ne_bytes(spec[0..8].try_into().unwrap());
   350	        let length = u64::from_ne_bytes(spec[8..16].try_into().unwrap());
   351	        let next = u32::from_ne_bytes(spec[20..24].try_into().unwrap());
   352	        let type_field = &spec[24..24 + DM_MAX_TYPE_NAME];
   353	        let type_nul = type_field
   354	            .iter()
   355	            .position(|&b| b == 0)
   356	            .unwrap_or(type_field.len());
   357	        let type_name = String::from_utf8_lossy(&type_field[..type_nul]).into_owned();
   358	
   359	        let param_area = &self.buf[end..];
   360	        let param_nul = param_area
   361	            .iter()
   362	            .position(|&b| b == 0)
   363	            .unwrap_or(param_area.len());
   364	        let params = String::from_utf8_lossy(&param_area[..param_nul]).into_owned();
   365	
   366	        self.remaining -= 1;
   367	        self.offset = if next == 0 {
   368	            self.buf.len()
   369	        } else {
   370	            self.first.saturating_add(next as usize)
   371	        };
   372	
   373	        Some(Row {
   374	            start: sector_start,
   375	            length,
   376	            type_name,
   377	            params,
   378	            _mode: PhantomData,
   379	        })
   380	    }
   381	}
