   521	    /// Hand-builds a synthetic `DM_TABLE_STATUS`-shaped response buffer:
   522	    /// header + N `dm_target_spec` entries whose `next` fields use the
   523	    /// *read*-direction convention (offset from the *first* spec's start),
   524	    /// each followed by a NUL-terminated status string. Deliberately
   525	    /// independent of `TableBuilder` (the write-side builder), matching the
   526	    /// old `synthetic_table_status_response` helper.
   527	    fn synthetic_table_status_response(entries: &[(&[u8], &str)]) -> (Vec<u8>, u32) {
   528	        let first = DmHeader::SIZE;
   529	        let mut aligned_lens = Vec::with_capacity(entries.len());
   530	        let mut payload_len = 0usize;
   531	        for (_, params) in entries {
   532	            let aligned = (DM_TARGET_SPEC_SIZE + params.len() + 1).next_multiple_of(8);
   533	            aligned_lens.push(aligned);
   534	            payload_len += aligned;
   535	        }
   536	        let mut bytes = vec![0u8; first + payload_len];
   537	
   538	        let mut abs_offset_from_first = 0usize;
   539	        for (i, (type_name, params)) in entries.iter().enumerate() {
   540	            let abs_offset = first + abs_offset_from_first;
   541	            let aligned_len = aligned_lens[i];
   542	            let next = if i == entries.len() - 1 {
   543	                0
   544	            } else {
   545	                (abs_offset_from_first + aligned_len) as u32
   546	            };
   547	
   548	            bytes[abs_offset..abs_offset + 8].copy_from_slice(&0u64.to_ne_bytes()); // sector_start
   549	            bytes[abs_offset + 8..abs_offset + 16].copy_from_slice(&0u64.to_ne_bytes()); // length
   550	            bytes[abs_offset + 20..abs_offset + 24].copy_from_slice(&next.to_ne_bytes());
   551	            let type_field = &mut bytes[abs_offset + 24..abs_offset + 24 + DM_MAX_TYPE_NAME];
   552	            type_field[..type_name.len()].copy_from_slice(type_name);
   553	
   554	            let param_start = abs_offset + DM_TARGET_SPEC_SIZE;
   555	            bytes[param_start..param_start + params.len()].copy_from_slice(params.as_bytes());
   556	
   557	            abs_offset_from_first += aligned_len;
   558	        }
   559	
   560	        (bytes, entries.len() as u32)
   561	    }
