    22	impl Leg {
    23	    /// A delay leg: route I/O to `device` at `offset_sectors`, delayed
    24	    /// by `delay_ms` milliseconds.
    25	    #[must_use]
    26	    pub fn new(device: DevId, offset_sectors: u64, delay_ms: u32) -> Self {
