    34	
    35	/// Delays I/O to an underlying device, optionally applying a different
    36	/// leg to reads, writes, and flushes.
    37	///
    38	/// Only `read` is mandatory; any unset leg (`write`/`flush`) follows the
    39	/// `read` leg's device, offset, and delay.
    40	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    41	pub struct Delay {
    42	    /// Leg applied to read I/O; also the fallback for any unset leg.
    43	    pub read: Leg,
    44	    /// Leg applied to write I/O; falls back to `read` if `None`.
    45	    pub write: Option<Leg>,
    46	    /// Leg applied to flush I/O; falls back to `read` if `None`.
    47	    pub flush: Option<Leg>,
    48	}
    49	impl Target for Delay {
    50	    const TYPE_NAME: &'static str = "delay";
    51	    type Info = RawInfo;
    52	}
    53	impl fmt::Display for Delay {
    54	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    55	        let read = self.read;
    56	        write!(
    57	            f,
    58	            "{} {} {}",
    59	            read.device, read.offset_sectors, read.delay_ms
    60	        )?;
    61	        // Once any second leg exists, emit both write and flush explicitly
    62	        // (9-arg form): the kernel's 6-arg form would bind flush to the
    63	        // write leg, which would silently contradict "unset legs follow
    64	        // read". Each unset leg falls back to `read`.
    65	        if self.write.is_some() || self.flush.is_some() {
    66	            let w = self.write.unwrap_or(read);
    67	            write!(f, " {} {} {}", w.device, w.offset_sectors, w.delay_ms)?;
    68	            let fl = self.flush.unwrap_or(read);
    69	            write!(f, " {} {} {}", fl.device, fl.offset_sectors, fl.delay_ms)?;
    70	        }
    71	        Ok(())
    72	    }
    73	}
