    11	/// Which I/O direction a [`Feature::CorruptBioByte`] targets.
    12	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    13	#[non_exhaustive]
    14	pub enum Direction {
    15	    /// Corrupt matching read I/O.
    16	    Read,
    17	    /// Corrupt matching write I/O.
    18	    Write,
    19	}
    20	
    21	/// One feature flag of a [`Flakey`] mapping. A closed set: the kernel
    22	/// target supports exactly these six, no more.
    23	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
    24	#[non_exhaustive]
    25	pub enum Feature {
    26	    /// Fail all reads during the down interval.
    27	    ErrorReads,
    28	    /// Silently discard writes during the down interval.
    29	    DropWrites,
    30	    /// Fail all writes during the down interval.
    31	    ErrorWrites,
    32	    /// Overwrite one byte of matching bios during the down interval.
    33	    /// `nth_byte` is 1-based (the kernel rejects 0).
    34	    CorruptBioByte {
    35	        /// 1-based index of the byte to overwrite within each bio.
    36	        nth_byte: u32,
    37	        /// Whether reads or writes are corrupted.
    38	        direction: Direction,
    39	        /// The byte value written in place of the original.
    40	        value: u8,
    41	        /// Bio-opcode flags restricting which bios are affected (`0` for
    42	        /// all).
    43	        flags: u32,
    44	    },
    45	    /// Randomly corrupt a byte in read bios. `probability` is the chance
    46	    /// per bio in the kernel range `0..=1_000_000_000` (1e9 = 100%).
    47	    RandomReadCorrupt {
    48	        /// Per-bio corruption chance in `0..=1_000_000_000` (1e9 = 100%).
    49	        probability: u32,
    50	    },
    51	    /// Randomly corrupt a byte in write bios. `probability` is the chance
    52	    /// per bio in the kernel range `0..=1_000_000_000` (1e9 = 100%).
    53	    RandomWriteCorrupt {
    54	        /// Per-bio corruption chance in `0..=1_000_000_000` (1e9 = 100%).
    55	        probability: u32,
    56	    },
    57	}
    58	
    59	impl Feature {
    60	    /// A discriminant identifying the feature *kind*, ignoring payload —
    61	    /// used to reject duplicate feature kinds.
    62	    fn kind(&self) -> u8 {
    63	        match self {
    64	            Feature::ErrorReads => 0,
    65	            Feature::DropWrites => 1,
    66	            Feature::ErrorWrites => 2,
    67	            Feature::CorruptBioByte { .. } => 3,
    68	            Feature::RandomReadCorrupt { .. } => 4,
    69	            Feature::RandomWriteCorrupt { .. } => 5,
    70	        }
    71	    }
    72	}
    73	
    74	// Raw *argument-token* count a `Feature` contributes to the table line's
    75	// `<#num_features>` field: the count is of tokens, not feature groups, so
    76	// a bare flag is 1 token, `corrupt_bio_byte` is 5 (itself plus 4 args),
    77	// and the `random_*_corrupt` features are 2 (themselves plus 1 arg each).
    78	fn flakey_feature_token_count(feature: &Feature) -> u32 {
    79	    match feature {
    80	        Feature::ErrorReads | Feature::DropWrites | Feature::ErrorWrites => 1,
    81	        Feature::CorruptBioByte { .. } => 5,
    82	        Feature::RandomReadCorrupt { .. } | Feature::RandomWriteCorrupt { .. } => 2,
    83	    }
    84	}
