     2	
     3	//! The `writecache` target: caches writes on a fast device (SSD or
     4	//! persistent memory) in front of a slower origin device.
     5	
     6	use std::fmt;
     7	
     8	use crate::DevId;
     9	use crate::table::{RawInfo, Target};
    10	
    11	/// The kernel's default high watermark (percent) when unset.
    12	const DEFAULT_HIGH_WATERMARK: u32 = 50;
    13	/// The kernel's default low watermark (percent) when unset.
    14	const DEFAULT_LOW_WATERMARK: u32 = 45;
    15	
    16	/// Backing store kind for a [`Writecache`] cache device.
    17	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    18	#[non_exhaustive]
    19	pub enum Kind {
    20	    /// A regular block device (SSD).
    21	    Ssd,
    22	    /// Persistent memory (DAX).
    23	    PersistentMemory,
    24	}
    25	
    26	/// A small fast device caching writes for a slower origin device. Only
    27	/// `high_watermark`/`low_watermark` are exposed; the rest of the kernel
    28	/// target's optional arguments are locked to their defaults. Build via
    29	/// [`Writecache::builder`].
    30	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
    31	#[non_exhaustive]
    32	pub struct Writecache {
    33	    kind: Kind,
    34	    origin: DevId,
    35	    cache: DevId,
    36	    block_size: u32,
    37	    high_watermark_percent: Option<u32>,
    38	    low_watermark_percent: Option<u32>,
    39	}
    40	impl Writecache {
    41	    /// Start building a [`Writecache`]. The watermark options default to
    42	    /// unset (kernel defaults).
    43	    #[must_use]
    44	    pub fn builder(kind: Kind, origin: DevId, cache: DevId, block_size: u32) -> Builder {
    45	        Builder {
    46	            kind,
    47	            origin,
    48	            cache,
    49	            block_size,
    50	            high_watermark_percent: None,
    51	            low_watermark_percent: None,
    52	        }
    53	    }
    54	
    55	    /// The backing store kind.
    56	    #[must_use]
    57	    pub fn kind(&self) -> Kind {
    58	        self.kind
    59	    }
    60	    /// The origin (slow) device.
    61	    #[must_use]
    62	    pub fn origin(&self) -> DevId {
    63	        self.origin
    64	    }
    65	    /// The cache (fast) device.
    66	    #[must_use]
    67	    pub fn cache(&self) -> DevId {
    68	        self.cache
    69	    }
    70	    /// The cache block size in bytes.
    71	    #[must_use]
    72	    pub fn block_size(&self) -> u32 {
    73	        self.block_size
    74	    }
    75	    /// The high watermark percentage, if set.
    76	    #[must_use]
    77	    pub fn high_watermark_percent(&self) -> Option<u32> {
    78	        self.high_watermark_percent
    79	    }
    80	    /// The low watermark percentage, if set.
    81	    #[must_use]
    82	    pub fn low_watermark_percent(&self) -> Option<u32> {
    83	        self.low_watermark_percent
    84	    }
    85	}
    86	impl Target for Writecache {
    87	    const TYPE_NAME: &'static str = "writecache";
    88	    type Info = RawInfo;
    89	}
    90	impl fmt::Display for Writecache {
    91	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    92	        let kind = match self.kind {
    93	            Kind::Ssd => 's',
    94	            Kind::PersistentMemory => 'p',
    95	        };
    96	        write!(
    97	            f,
    98	            "{kind} {} {} {}",
    99	            self.origin, self.cache, self.block_size
   100	        )?;
   101	        let opt_count = 2
   102	            * (u32::from(self.high_watermark_percent.is_some())
   103	                + u32::from(self.low_watermark_percent.is_some()));
   104	        write!(f, " {opt_count}")?;
   105	        if let Some(hw) = self.high_watermark_percent {
   106	            write!(f, " high_watermark {hw}")?;
   107	        }
   108	        if let Some(lw) = self.low_watermark_percent {
   109	            write!(f, " low_watermark {lw}")?;
   110	        }
   111	        Ok(())
   112	    }
   113	}
   114	
   115	/// Builder for [`Writecache`] — see [`Writecache::builder`].
   116	#[derive(Debug, Clone)]
   117	pub struct Builder {
   118	    kind: Kind,
   119	    origin: DevId,
   120	    cache: DevId,
   121	    block_size: u32,
   122	    high_watermark_percent: Option<u32>,
   123	    low_watermark_percent: Option<u32>,
   124	}
   125	impl Builder {
   126	    /// Start writeback once the cache is this percent full.
   127	    #[must_use]
   128	    pub fn high_watermark_percent(mut self, percent: u32) -> Self {
   129	        self.high_watermark_percent = Some(percent);
   130	        self
   131	    }
   132	    /// Stop writeback once the cache drops to this percent full.
   133	    #[must_use]
   134	    pub fn low_watermark_percent(mut self, percent: u32) -> Self {
   135	        self.low_watermark_percent = Some(percent);
   136	        self
   137	    }
   138	    /// Finish building the [`Writecache`].
   139	    ///
   140	    /// # Errors
   141	    ///
   142	    /// [`crate::Error::Usage`] if either watermark percentage exceeds
   143	    /// `100`, if both are set and `high < low`, or if `block_size` is not
   144	    /// a power of two or is below `512`.
   145	    pub fn build(self) -> Result<Writecache, crate::Error> {
   146	        if let Some(hw) = self.high_watermark_percent
   147	            && hw > 100
   148	        {
   149	            return Err(crate::Error::Usage(format!(
   150	                "writecache high_watermark must be <= 100, got {hw}"
   151	            )));
   152	        }
   153	        if let Some(lw) = self.low_watermark_percent
   154	            && lw > 100
   155	        {
   156	            return Err(crate::Error::Usage(format!(
   157	                "writecache low_watermark must be <= 100, got {lw}"
   158	            )));
   159	        }
   160	        // The kernel fills an unset watermark with its default (high 50,
   161	        // low 45) and *always* checks high >= low — so resolve the effective
   162	        // values before comparing, not only when both are set.
   163	        let effective_high = self
   164	            .high_watermark_percent
   165	            .unwrap_or(DEFAULT_HIGH_WATERMARK);
   166	        let effective_low = self.low_watermark_percent.unwrap_or(DEFAULT_LOW_WATERMARK);
   167	        if effective_high < effective_low {
   168	            return Err(crate::Error::Usage(format!(
   169	                "writecache high_watermark ({effective_high}) must be >= low_watermark ({effective_low})"
   170	            )));
   171	        }
   172	        if !self.block_size.is_power_of_two() || self.block_size < 512 {
   173	            return Err(crate::Error::Usage(format!(
   174	                "writecache block_size must be a power of two >= 512, got {}",
   175	                self.block_size
   176	            )));
   177	        }
   178	        Ok(Writecache {
   179	            kind: self.kind,
   180	            origin: self.origin,
   181	            cache: self.cache,
   182	            block_size: self.block_size,
   183	            high_watermark_percent: self.high_watermark_percent,
   184	            low_watermark_percent: self.low_watermark_percent,
   185	        })
   186	    }
   187	}
