   101	/// Exercises `snapshot::Merge`'s real handover procedure end to
   102	/// end: a `snapshot-origin` device, a `snapshot` device sharing its COW
   103	/// device, a write that creates a real COW exception, then the handover
   104	/// itself (suspend origin, reload it as `snapshot-merge`, suspend the old
   105	/// snapshot, resume) — followed by reading the written data back through
   106	/// the now-merged origin to prove the merge preserved it.
   107	///
   108	/// The exact sequencing was verified directly against `dm-snap.c`
   109	/// (`snapshot_preresume`/`snapshot_resume`): resuming a `snapshot-merge`
   110	/// target refuses with `EINVAL` unless the old `snapshot` target sharing
   111	/// its COW device is already suspended — that's what makes step 5 below
   112	/// load-bearing, not optional.
   113	#[test]
   114	fn snapshot_merge_takes_over_from_snapshot_and_merges() {
   115	    let Some(control) = open_control() else {
   116	        return;
   117	    };
   118	    ensure_module_loaded("dm-snapshot");
   119	
   120	    let origin_backing = LoopDevice::create("snapmerge-origin", 16 * 1024 * 1024);
   121	    let cow_backing = LoopDevice::create("snapmerge-cow", 16 * 1024 * 1024);
   122	    let origin_backing_device = control
   123	        .by_node(&origin_backing.path)
   124	        .expect("by_node origin backing");
   125	    let cow_device = control.by_node(&cow_backing.path).expect("by_node cow");
   126	    let origin_len_sectors = 16 * 1024 * 1024 / 512;
   127	
   128	    // 1. Origin device: dm-linear-equivalent passthrough (snapshot-origin
   129	    //    with no snapshot yet just forwards I/O) to the backing device.
   130	    let origin_name = format!("devmap-test-snapmerge-origin-{}", std::process::id());
   131	    let origin_removed = control.create(&origin_name).expect("DM_DEV_CREATE origin");
   132	    origin_removed
   133	        .builder()
   134	        .add(
   135	            0,
   136	            origin_len_sectors,
   137	            snapshot::Origin {
   138	                origin: origin_backing_device.id(),
   139	            },
   140	        )
   141	        .expect("add snapshot-origin")
   142	        .load()
   143	        .expect("DM_TABLE_LOAD origin");
   144	    origin_removed.resume().expect("resume origin");
   145	
   146	    // 2. Write a first pattern before any snapshot exists.
   147	    let origin_minor = origin_removed.id().minor();
   148	    let origin_path = format!("/dev/dm-{origin_minor}");
   149	    write_block(&origin_path, 0, 0xAA);
   150	
   151	    // 3. A persistent snapshot of that origin, sharing the same COW
   152	    //    device the eventual snapshot-merge target will take over.
   153	    let snap_name = format!("devmap-test-snapmerge-snap-{}", std::process::id());
   154	    let snap_removed = control.create(&snap_name).expect("DM_DEV_CREATE snapshot");
   155	    snap_removed
   156	        .builder()
   157	        .add(
   158	            0,
   159	            origin_len_sectors,
   160	            Snapshot::new(origin_backing_device.id(), cow_device.id(), 8).expect("valid snapshot"),
   161	        )
   162	        .expect("add snapshot")
   163	        .load()
   164	        .expect("DM_TABLE_LOAD snapshot");
   165	    snap_removed.resume().expect("resume snapshot");
   166	
   167	    // 4. Write a second pattern now that the snapshot is active. This is
   168	    //    the divergence a merge undoes: dm-snapshot preserves the *old*
   169	    //    (pre-write) contents of this chunk in the COW device before
   170	    //    letting the write through to the origin, so the snapshot's view
   171	    //    of this chunk is now the all-zero data that was here before —
   172	    //    merging will restore exactly that, overwriting this 0xBB write.
   173	    write_block(&origin_path, 1, 0xBB);
