   175	    // 5. Handover: suspend the origin, stage snapshot-merge on it,
   176	    //    suspend the old snapshot device (required precondition per
   177	    //    dm-snap.c's snapshot_preresume), then resume the origin —
   178	    //    activating the merge, which runs in the background.
   179	    origin_removed.suspend().expect("suspend origin");
   180	    origin_removed
   181	        .builder()
   182	        .add(
   183	            0,
   184	            origin_len_sectors,
   185	            snapshot::Merge::new(origin_backing_device.id(), cow_device.id(), 8)
   186	                .expect("valid snapshot-merge"),
   187	        )
   188	        .expect("add snapshot-merge")
   189	        .load()
   190	        .expect("DM_TABLE_LOAD snapshot-merge");
   191	    snap_removed
   192	        .suspend()
   193	        .expect("suspend old snapshot before handover");
   194	    origin_removed.resume().expect("resume as snapshot-merge");
   195	
   196	    // 6. Wait for the background merge to finish: sectors_allocated drops
   197	    //    to exactly metadata_sectors once nothing is left to fold in.
   198	    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
   199	    loop {
