   201	        assert_eq!(status.target_count(), 1);
   202	        let reported: Vec<_> = origin_removed.info().expect("DM_TABLE_STATUS").collect();
   203	        // snapshot-merge's runtime status isn't typed by this crate, so it
   204	        // parses back as `RawInfo` — the merge-completion check reads the
   205	        // raw status string directly.
   206	        if let Some(RawInfo(params)) = reported[0].parse::<snapshot::Merge>() {
