     3	//! Real-kernel coverage for `dm-zoned`, using a `null_blk`-emulated
     4	//! host-managed zoned block device instead of real ZBC/ZAC hardware.
     5	//!
     6	//! Unlike every other target in this crate, `dm-zoned` requires its
     7	//! backing device to already carry valid on-disk metadata — the kernel
     8	//! target has no self-formatting fallback (confirmed against
     9	//! `dm-zoned-metadata.c`: an all-zero superblock is rejected outright,
    10	//! unlike `dm-integrity`'s "format on first load" behavior). That
    11	//! metadata is written by the external `dmzadm` tool (packaged as
    12	//! `dm-zoned-tools`), so this test skips gracefully if it isn't
    13	//! installed, the same way other tests skip for missing root.
    14	
    15	mod common;
    16	
    17	use std::io::{Read, Seek, SeekFrom, Write};
    18	use std::process::Command;
    19	
    20	use common::{ensure_module_loaded, open_control};
    21	use devmap::targets::Zoned;
    22	
    23	/// Whether `name` resolves on `$PATH`. Used to skip if `dmzadm` isn't
    24	/// installed, the same way `common::open_control` skips for missing root.
    25	fn command_exists(name: &str) -> bool {
    26	    Command::new("which")
    27	        .arg(name)
    28	        .stdout(std::process::Stdio::null())
    29	        .status()
    30	        .is_ok_and(|s| s.success())
    31	}
    32	
    33	/// A `null_blk`-emulated host-managed zoned block device (`/dev/nullb0`),
    34	/// for exercising `dm-zoned` without real ZBC/ZAC hardware. `null_blk`
    35	/// only supports one global module instance at a time — fine here since
    36	/// this is the only test using it, and real-kernel integration binaries
    37	/// in this crate already run single-threaded (`--test-threads=1`).
    38	///
    39	/// Returns `None` (and prints a skip notice) if `null_blk` can't be
    40	/// loaded in zoned mode — e.g. a kernel built without
    41	/// `CONFIG_BLK_DEV_NULL_BLK` zoned support.
    42	struct NullBlkZonedDevice {
    43	    path: &'static str,
    44	}
    45	
    46	impl NullBlkZonedDevice {
    47	    /// `zone_size_mb` must be a power of two; `gb` must be a multiple of it.
    48	    fn create(zone_size_mb: u32, zone_nr_conv: u32, gb: u32) -> Option<Self> {
    49	        let _ = Command::new("modprobe")
    50	            .args(["-q", "-r", "null_blk"])
    51	            .status();
    52	        let status = Command::new("modprobe")
    53	            .arg("null_blk")
    54	            .arg("nr_devices=1")
    55	            .arg("zoned=1")
    56	            .arg("memory_backed=1")
    57	            .arg(format!("zone_size={zone_size_mb}"))
    58	            .arg(format!("zone_nr_conv={zone_nr_conv}"))
    59	            .arg(format!("gb={gb}"))
    60	            .status();
    61	        if !status.is_ok_and(|s| s.success()) || !std::path::Path::new("/dev/nullb0").exists() {
    62	            eprintln!("skip: null_blk zoned emulation unavailable on this kernel");
    63	            return None;
    64	        }
    65	        Some(Self {
    66	            path: "/dev/nullb0",
    67	        })
    68	    }
    69	}
    70	
    71	impl Drop for NullBlkZonedDevice {
    72	    fn drop(&mut self) {
    73	        let _ = Command::new("modprobe")
    74	            .args(["-q", "-r", "null_blk"])
    75	            .status();
    76	    }
    77	}
