    79	#[test]
    80	fn zoned_formats_with_dmzadm_and_passes_data_through() {
    81	    let Some(control) = open_control() else {
    82	        return;
    83	    };
    84	    if !command_exists("dmzadm") {
    85	        eprintln!("skip: requires the dmzadm tool (package: dm-zoned-tools)");
    86	        return;
    87	    }
    88	    ensure_module_loaded("dm-zoned");
    89	
    90	    let Some(zoned) = NullBlkZonedDevice::create(4, 8, 1) else {
    91	        return;
    92	    };
    93	
    94	    let format = Command::new("dmzadm")
    95	        .arg("--format")
    96	        .arg(zoned.path)
    97	        .output()
    98	        .expect("run dmzadm --format");
    99	    assert!(
   100	        format.status.success(),
   101	        "dmzadm --format failed: {}",
   102	        String::from_utf8_lossy(&format.stderr)
   103	    );
   104	
   105	    let zoned_device = control.by_node(zoned.path).expect("by_node zoned device");
   106	
   107	    // dm-zoned's usable size is smaller than the raw device (some zones
   108	    // are reserved for metadata/reclaim) and that reservation isn't
   109	    // something devmap computes — `dmzadm --start` already knows it, so
   110	    // ask it once via a throwaway device rather than guessing. `dmzadm`
   111	    // names the device `dmz-<basename>` (e.g. `dmz-nullb0`).
   112	    let start = Command::new("dmzadm")
   113	        .arg("--start")
   114	        .arg(zoned.path)
   115	        .output()
   116	        .expect("run dmzadm --start");
   117	    assert!(
   118	        start.status.success(),
   119	        "dmzadm --start failed: {}",
   120	        String::from_utf8_lossy(&start.stderr)
   121	    );
   122	    let dm_name = format!("dmz-{}", zoned.path.trim_start_matches("/dev/"));
   123	    let table_output = Command::new("dmsetup")
   124	        .args(["table", &dm_name])
   125	        .output()
