   127	    let table_line = String::from_utf8_lossy(&table_output.stdout)
   128	        .trim()
   129	        .to_string();
   130	    let usable_sectors: u64 = table_line
   131	        .split_whitespace()
   132	        .nth(1)
   133	        .expect("table line has a length field")
   134	        .parse()
   135	        .expect("parse length");
   136	    Command::new("dmsetup")
   137	        .args(["remove", &dm_name])
   138	        .status()
   139	        .expect("dmsetup remove probe device");
