     3	//! Shared helpers for real-kernel integration tests: a root-gated
     4	//! `Control::open()` skip check, and a sparse-file-backed loop device for
     5	//! tests that need a real (if tiny) block device without touching real
     6	//! hardware.
     7	//!
     8	//! Every test binary that `mod common;`s this file compiles the whole
     9	//! thing but typically uses only part of it (e.g. `zoned_target.rs`
    10	//! doesn't need `LoopDevice`) — `#![allow(dead_code)]` avoids per-binary
    11	//! false-positive dead-code warnings from that, not from genuinely
    12	//! unused code.
    13	#![allow(dead_code)]
    14	
    15	use std::fs::File;
    16	use std::path::PathBuf;
    17	use std::process::Command;
    18	use std::sync::atomic::{AtomicU64, Ordering};
    19	
    20	use devmap::Control;
    21	
    22	static NEXT_ID: AtomicU64 = AtomicU64::new(0);
    23	
    24	/// Returns `None` (and prints a skip notice) if this process can't open
    25	/// `/dev/mapper/control` — i.e. isn't root / doesn't have `CAP_SYS_ADMIN`.
    26	pub(crate) fn open_control() -> Option<Control> {
    27	    if let Ok(control) = Control::open() {
    28	        return Some(control);
    29	    }
    30	    eprintln!("skip: requires root (or CAP_SYS_ADMIN) for /dev/mapper/control");
    31	    None
    32	}
    33	
    34	/// A sparse backing file attached as a loop device via `losetup`. Detaches
    35	/// the loop device and deletes the backing file on drop (best-effort).
    36	pub(crate) struct LoopDevice {
    37	    pub(crate) path: String,
    38	    file_path: PathBuf,
    39	}
    40	
    41	impl LoopDevice {
    42	    /// Creates a `size_bytes`-sized sparse file and attaches it.
    43	    pub(crate) fn create(name: &str, size_bytes: u64) -> Self {
    44	        let id = NEXT_ID.fetch_add(1, Ordering::Relaxed);
    45	        let file_path =
    46	            std::env::temp_dir().join(format!("devmap-test-{name}-{}-{id}", std::process::id()));
    47	        let file = File::create(&file_path).expect("create backing file");
    48	        file.set_len(size_bytes).expect("set_len backing file");
    49	        drop(file);
    50	
    51	        let output = Command::new("losetup")
    52	            .args(["-f", "--show"])
    53	            .arg(&file_path)
    54	            .output()
    55	            .expect("run losetup -f --show");
    56	        assert!(
    57	            output.status.success(),
    58	            "losetup failed: {}",
    59	            String::from_utf8_lossy(&output.stderr)
    60	        );
    61	        let path = String::from_utf8(output.stdout)
    62	            .expect("losetup output is utf8")
    63	            .trim()
    64	            .to_string();
    65	
    66	        Self { path, file_path }
    67	    }
    68	}
    69	
    70	impl Drop for LoopDevice {
    71	    fn drop(&mut self) {
    72	        let _ = Command::new("losetup").args(["-d", &self.path]).status();
    73	        let _ = std::fs::remove_file(&self.file_path);
    74	    }
    75	}
    76	
    77	/// Best-effort `modprobe` for a dm target's kernel module. Most targets
    78	/// auto-load via `request_module` when first referenced in a table, but
    79	/// this makes failures easier to diagnose than a bare `ENOENT`/`EINVAL`
    80	/// from `DM_TABLE_LOAD`. Ignored if it fails (e.g. already built in).
    81	pub(crate) fn ensure_module_loaded(name: &str) {
    82	    let _ = Command::new("modprobe").arg("-q").arg(name).status();
    83	}

### README.md
     1	# devmap
     2	
     3	A high-level, safe Rust interface to the Linux **device-mapper** control
     4	ioctls. Create device-mapper devices, build and load their tables, read
     5	tables and runtime status back, suspend/resume, and send target messages —
     6	all through typed Rust rather than hand-packed `struct dm_ioctl` buffers.
     7	
     8	Built on [`iocuddle`](https://crates.io/crates/iocuddle); the only `unsafe`
     9	in the crate is the ioctl-number declarations, confined to one module.
    10	
    11	## Requirements
    12	
    13	- **Linux** (device-mapper is a Linux subsystem).
    14	- **`CAP_SYS_ADMIN`** (typically root) to open `/dev/mapper/control`.
    15	
    16	## Quick start
    17	
    18	```rust
    19	use devmap::{Control, targets::{Zero, Linear}, DevId};
    20	
    21	fn main() -> Result<(), devmap::Error> {
    22	    let control = Control::open()?;              // /dev/mapper/control
    23	    let dev = control.create("my-device")?;     // a `Removed` guard
    24	
    25	    // Build a table one target at a time, straight into one load buffer.
    26	    dev.builder()
    27	        .add(0,    8192, Zero)?                                  // 8192 sectors of zero
    28	        .add(8192, 1024, Linear { device: DevId::new(252, 0), offset_sectors: 0 })?
    29	        .load()?;                                               // DM_TABLE_LOAD
    30	    dev.resume()?;                                              // activate the staged table
    31	
    32	    let status = dev.status()?;
    33	    println!("{} — {} target(s), open_count {}",
    34	             dev.id(), status.target_count(), status.open_count());
    35	
    36	    Ok(())
    37	}   // `dev` drops here -> the device is removed
    38	```
    39	
    40	## The model
    41	
    42	- **`Control`** — the `/dev/mapper/control` fd; a factory for devices:
    43	  `open`, `create`, `by_device`, `by_node`, `by_name`, `by_uuid`, `list`.
    44	- **`Device`** — a plain handle identified by a **`DevId`** (`major:minor`).
    45	  Everything else lives here: `builder`, `suspend`, `resume`, `remove`,
    46	  `status`, `table`, `info`, `message`.
    47	- **`Removed`** — the auto-removing guard `Control::create` returns:
    48	  dropping it removes the device. Convert it into a plain `Device` to keep
    49	  the device alive.
    50	
    51	## Building tables
    52	
    53	`Device::builder()` streams targets into a single `DM_TABLE_LOAD` buffer;
    54	`add` validates each target and `load` issues the ioctl. Targets are
    55	structs in [`devmap::targets`]:
    56	
    57	`zero`, `error`, `linear`, `striped`, `unstriped`, `dust`, `era`,
    58	`log_writes`, `zoned`, `thin`, `verity`, `delay`, `flakey`, `writecache`,
    59	`integrity`, `raid`, `thin_pool`, `snapshot` (`Snapshot`/`Origin`/`Merge`).
    60	
    61	Targets with kernel-enforced constraints are built through validating
    62	constructors (`Verity::new`, `Raid::new`, `ThinPool::builder()…build()`,
    63	…) that reject values the kernel would refuse — so a bad table fails
    64	early with `Error::Usage` instead of an opaque `EINVAL` at load time.
    65	
    66	## Reading tables back
    67	
    68	Two reads, distinguished by what the kernel returns:
    69	
    70	```rust
    71	// The mapping (STATUSTYPE_TABLE) — reconstruct the target you loaded:
    72	for row in dev.table()? {
    73	    if let Some(lin) = row.parse::<Linear>() {
    74	        println!("{}..{} -> {}", row.start(), row.length(), lin.device);
    75	    }
    76	}
    77	
    78	// Runtime status (STATUSTYPE_INFO) — per-target status. `parse::<T>()`
    79	// returns T's runtime-status type (`RawInfo` unless a target models one):
    80	for row in dev.info()? {
    81	    if let Some(devmap::RawInfo(status)) = row.parse::<Linear>() {
    82	        println!("{} linear: {status}", row.start());
    83	    }
    84	}
    85	```
    86	
    87	`Row::parse::<T>()` is name-checked and mode-safe: a `table()` row yields
    88	the target, an `info()` row yields its `Target::Info` status type, and you
    89	can't cross the two.
    90	
    91	## Custom targets
    92	
    93	The target set is open. Implement `Target` (plus `Display` to render its
    94	params, and optionally `FromStr` to read it back) for any kernel target
    95	this crate doesn't model:
    96	
    97	```rust
    98	use std::fmt;
    99	use devmap::{Target, RawInfo};
   100	
   101	struct MyTarget { /* … */ }
   102	impl Target for MyTarget {
   103	    const TYPE_NAME: &'static str = "my-target";
   104	    type Info = RawInfo;
   105	}
   106	impl fmt::Display for MyTarget {
   107	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
   108	        write!(f, "…kernel params…")
   109	    }
   110	}
   111	// dev.builder().add(0, len, MyTarget { .. })?.load()?;
   112	```
   113	
   114	## Testing
   115	
   116	Unit tests run anywhere; the integration tests under `tests/` need root
   117	(they create real loop and dm devices and clean them up):
   118	
   119	```sh
   120	cargo test              # unit tests; integration tests skip without root
   121	sudo -E cargo test      # full suite, exercising the real ioctls
   122	```
   123	
   124	## License
   125	
